<script setup lang="ts">
import * as echarts from 'echarts'
import { Refresh } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { addOperationActionComment, assignOperationAction, createOperationAction, getOperationAction, getOperationActions, getOperationActionStatistics, updateOperationActionStatus } from '../../api/operationAction'
import { useUserStore } from '../../stores/user'
import type { CreateActionRequest, OperationAction, OperationActionPriority, OperationActionStatistics, OperationActionStatus } from '../../types/operationAction'
import { getApiErrorMessage } from '../../utils/api-error'

const userStore = useUserStore()
const isAdmin = computed(() => userStore.currentUser?.role_code === 'ADMINISTRATOR')
const loading = ref(false); const errorMessage = ref(''); const actions = ref<OperationAction[]>([]); const statistics = ref<OperationActionStatistics | null>(null)
const page = ref(1); const pageSize = ref(20); const total = ref(0); const status = ref<OperationActionStatus | ''>(''); const priority = ref<OperationActionPriority | ''>('')
const detail = ref<OperationAction | null>(null); const comment = ref(''); const assigneeId = ref<number | null>(null); const createVisible = ref(false); const creating = ref(false)
const form = ref<CreateActionRequest>({ title: '', description: '', priority: 'MEDIUM' })
const chartContainer = ref<HTMLDivElement | null>(null); let chart: echarts.ECharts | null = null
const statusLabels: Record<OperationActionStatus, string> = { OPEN: '待处理', IN_PROGRESS: '处理中', COMPLETED: '已完成', CANCELLED: '已取消' }
const priorityLabels: Record<OperationActionPriority, string> = { LOW: '低', MEDIUM: '中', HIGH: '高' }
const sourceLabels: Record<string, string> = { ANOMALY: '异常', QUALITY: '质量', SCORE: '评分', MANUAL: '人工' }
function statusLabel(value: OperationActionStatus): string { return statusLabels[value] }
function priorityLabel(value: OperationActionPriority): string { return priorityLabels[value] }
function sourceLabel(value: string): string { return sourceLabels[value] || value }
function formatDate(value: string | null): string { if (!value) return '--'; const d = new Date(value); return Number.isNaN(d.getTime()) ? value : new Intl.DateTimeFormat('zh-CN', { dateStyle: 'medium', timeStyle: 'short' }).format(d) }
function errorText(error: unknown): string { return getApiErrorMessage(error, '运营行动数据加载失败，请稍后重试。') }
async function load(): Promise<void> { if (loading.value) return; loading.value = true; errorMessage.value = ''; const [list, stats] = await Promise.allSettled([getOperationActions({ page: page.value, page_size: pageSize.value, ...(status.value ? { status: status.value } : {}), ...(priority.value ? { priority: priority.value } : {}) }), getOperationActionStatistics()]); if (list.status === 'fulfilled') { actions.value = list.value.items; total.value = list.value.total }; if (stats.status === 'fulfilled') { statistics.value = stats.value; await nextTick(); renderChart() }; const failure = [list, stats].find((item) => item.status === 'rejected'); if (failure) errorMessage.value = errorText(failure.status === 'rejected' ? failure.reason : null); loading.value = false }
async function openDetail(item: OperationAction): Promise<void> { try { detail.value = await getOperationAction(item.action_id); assigneeId.value = detail.value.assignee_user?.user_id ?? null } catch (error: unknown) { errorMessage.value = errorText(error) } }
async function changeStatus(value: OperationActionStatus): Promise<void> { if (!detail.value || !isAdmin.value) return; try { detail.value = await updateOperationActionStatus(detail.value.action_id, value); await load(); ElMessage.success('状态已更新') } catch (error: unknown) { errorMessage.value = errorText(error) } }
async function assign(): Promise<void> { if (!detail.value || !isAdmin.value || !assigneeId.value) return; try { detail.value = await assignOperationAction(detail.value.action_id, assigneeId.value); await load(); ElMessage.success('负责人已更新') } catch (error: unknown) { errorMessage.value = errorText(error) } }
async function submitComment(): Promise<void> { if (!detail.value || !comment.value.trim()) return; try { await addOperationActionComment(detail.value.action_id, comment.value.trim()); comment.value = ''; await openDetail(detail.value); ElMessage.success('评论已添加') } catch (error: unknown) { errorMessage.value = errorText(error) } }
async function create(): Promise<void> { if (!isAdmin.value || !form.value.title.trim()) return; creating.value = true; try { await createOperationAction(form.value); createVisible.value = false; form.value = { title: '', description: '', priority: 'MEDIUM' }; await load(); ElMessage.success('行动已创建') } catch (error: unknown) { errorMessage.value = errorText(error) } finally { creating.value = false } }
function renderChart(): void { if (!chartContainer.value || !statistics.value) return; chart ??= echarts.init(chartContainer.value); const s = statistics.value; chart.setOption({ tooltip: { trigger: 'item' }, legend: { bottom: 0 }, series: [{ type: 'pie', radius: ['45%', '70%'], data: [{ name: '待处理', value: s.OPEN }, { name: '处理中', value: s.IN_PROGRESS }, { name: '已完成', value: s.COMPLETED }, { name: '已取消', value: s.CANCELLED }] }] }, true) }
function resizeChart(): void { chart?.resize() }
onMounted(() => { window.addEventListener('resize', resizeChart); void load() }); onBeforeUnmount(() => { window.removeEventListener('resize', resizeChart); chart?.dispose(); chart = null })
</script>

<template>
  <main class="action-page"><header class="page-header"><div><p class="eyebrow">Operation Action Center</p><h1>运营行动与告警处置</h1><p class="subtitle">承接分析结果，追踪分派、处理和关闭过程。</p></div><div class="header-actions"><router-link to="/dashboard"><el-button>返回驾驶舱</el-button></router-link><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button><el-button v-if="isAdmin" type="primary" @click="createVisible = true">新建行动</el-button></div></header>
    <el-alert v-if="errorMessage" type="error" show-icon :title="errorMessage" :closable="false" class="page-error" />
    <section class="stats-grid" v-loading="loading"><el-card v-for="item in [{ label: '行动总数', value: statistics?.total }, { label: '待处理', value: statistics?.OPEN }, { label: '处理中', value: statistics?.IN_PROGRESS }, { label: '已完成', value: statistics?.COMPLETED }, { label: '已取消', value: statistics?.CANCELLED }]" :key="item.label"><span class="metric-label">{{ item.label }}</span><strong class="metric-value">{{ item.value ?? '--' }}</strong></el-card></section>
    <section class="content-grid"><el-card shadow="never"><template #header><div class="card-header"><strong>行动列表</strong><div class="filters"><el-select v-model="status" clearable placeholder="状态" @change="page = 1; load()"><el-option v-for="item in ['OPEN','IN_PROGRESS','COMPLETED','CANCELLED']" :key="item" :label="statusLabel(item as OperationActionStatus)" :value="item" /></el-select><el-select v-model="priority" clearable placeholder="优先级" @change="page = 1; load()"><el-option v-for="item in ['LOW','MEDIUM','HIGH']" :key="item" :label="priorityLabel(item as OperationActionPriority)" :value="item" /></el-select></div></div></template><el-table :data="actions" row-key="action_id" empty-text="暂无运营行动" @row-click="openDetail"><el-table-column prop="title" label="标题" min-width="180" show-overflow-tooltip /><el-table-column label="状态" width="100"><template #default="scope">{{ statusLabel(scope.row.status) }}</template></el-table-column><el-table-column label="优先级" width="90"><template #default="scope">{{ priorityLabel(scope.row.priority) }}</template></el-table-column><el-table-column label="负责人" width="120"><template #default="scope">{{ scope.row.assignee_user?.display_name || scope.row.assignee_user?.username || '未分派' }}</template></el-table-column><el-table-column label="来源" width="100"><template #default="scope">{{ scope.row.sources[0] ? sourceLabel(scope.row.sources[0].source_type) : '人工' }}</template></el-table-column><el-table-column label="创建时间" width="150"><template #default="scope">{{ formatDate(scope.row.created_at) }}</template></el-table-column></el-table><el-pagination v-if="total" v-model:current-page="page" v-model:page-size="pageSize" class="pagination" layout="total, sizes, prev, pager, next" :total="total" :page-sizes="[20,50,100]" @current-change="load" @size-change="load" /></el-card><el-card shadow="never"><template #header><strong>状态分布</strong></template><div ref="chartContainer" class="chart" /><el-empty v-if="!statistics" description="暂无统计数据" /></el-card></section>
    <el-drawer :model-value="detail !== null" title="行动详情" size="520px" @close="detail = null"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="标题">{{ detail.title }}</el-descriptions-item><el-descriptions-item label="描述">{{ detail.description || '--' }}</el-descriptions-item><el-descriptions-item label="状态"><el-select v-if="isAdmin" :model-value="detail.status" @change="changeStatus"><el-option v-for="item in ['OPEN','IN_PROGRESS','COMPLETED','CANCELLED']" :key="item" :label="statusLabels[item as OperationActionStatus]" :value="item" /></el-select><span v-else>{{ statusLabels[detail.status] }}</span></el-descriptions-item><el-descriptions-item label="优先级">{{ priorityLabels[detail.priority] }}</el-descriptions-item><el-descriptions-item label="负责人">{{ detail.assignee_user?.display_name || detail.assignee_user?.username || '未分派' }}</el-descriptions-item></el-descriptions><div v-if="isAdmin" class="assign-row"><el-input-number v-model="assigneeId" :min="1" placeholder="负责人用户ID" /><el-button @click="assign">分派</el-button></div><el-divider>来源证据</el-divider><el-empty v-if="!detail.sources.length" description="无来源证据" /><div v-for="source in detail.sources" :key="source.source_id" class="source-item"><el-tag>{{ sourceLabels[source.source_type] }}</el-tag><span>{{ source.source_evidence_summary }}</span><small>{{ formatDate(source.source_analysis_as_of) }} · {{ source.source_algorithm_version || '人工' }}</small></div><el-divider>处理记录</el-divider><el-timeline><el-timeline-item v-for="item in detail.history" :key="item.history_id" :timestamp="formatDate(item.created_at)">{{ item.event_type }}：{{ item.comment || '--' }}</el-timeline-item></el-timeline><div class="comment-row"><el-input v-model="comment" type="textarea" :rows="2" placeholder="添加处理记录" /><el-button type="primary" @click="submitComment">提交评论</el-button></div></template></el-drawer>
    <el-dialog v-model="createVisible" title="新建运营行动" width="520px"><el-form label-width="80px"><el-form-item label="标题"><el-input v-model="form.title" /></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" /></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority"><el-option v-for="item in ['LOW','MEDIUM','HIGH']" :key="item" :label="priorityLabels[item as OperationActionPriority]" :value="item" /></el-select></el-form-item></el-form><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="creating" @click="create">创建</el-button></template></el-dialog>
  </main>
</template>

<style scoped>
.action-page{min-height:100vh;padding:28px;background:var(--el-bg-color-page);color:var(--el-text-color-primary)}.page-header,.card-header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.header-actions,.filters{display:flex;gap:10px;flex-wrap:wrap}.eyebrow,.subtitle,.metric-label{margin:0;color:var(--el-text-color-secondary)}.eyebrow{color:var(--el-color-primary);font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.page-error{margin:20px 0}.stats-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;margin:24px 0}.metric-value{display:block;margin-top:12px;font-size:28px}.content-grid{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(280px,1fr);gap:20px}.chart{height:300px}.pagination{justify-content:flex-end;margin-top:18px}.assign-row,.comment-row{display:flex;gap:10px;margin:16px 0}.source-item{display:grid;gap:6px;padding:10px 0;border-bottom:1px solid var(--el-border-color-lighter)}.source-item small{color:var(--el-text-color-secondary)}@media(max-width:900px){.stats-grid{grid-template-columns:repeat(2,1fr)}.content-grid{grid-template-columns:1fr}.page-header{flex-direction:column}}
</style>
